import React, { useState } from "react";
import RatingStars from "../components/RatingStars";
import ChaiList from "../components/ChaiList";

function Home({ 
  entries = [], onAdd, onDelete }) 
 {
  const [style, setStyle] = useState("Masala");
  const [rating, setRating] = useState(0);
  const [notes, setNotes] = useState("");

  function handleSubmit(e) {
    e.preventDefault();
    if (!onAdd) return;

    const now = new Date();
    const entry = {
      id: crypto.randomUUID?.() || String(Date.now()),
      dateISO: now.toISOString().slice(0, 10),
      time: now.toTimeString().slice(0, 5),
      style,
      rating,
      notes: notes.trim()
    };

    onAdd(entry);
    setStyle("Masala");
    setRating('*');
    setNotes("");
  }

  return (
    <section className="page">
      <h1>Chai Rating</h1>

      <form onSubmit={handleSubmit} className="card" aria-label="add cup">
        <label>
          Type
          <select value={style} onChange={(e) => setStyle(e.target.value)}>
            <option>Masala</option>
            <option>Adrak</option>
            <option>Elaichi</option>
            <option>Kashmiri</option>
            <option>Cutting</option>
            <option>Filter</option>
            <option>Other(?)</option>

          </select>
        </label>

        <label>
          What's the tea? o_0  
          <textarea
            placeholder="divulge ':| "
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
          />
        </label>

        <div>

<div>Rating</div>
  <RatingStars value={rating} onChange={setRating} />
</div>


        <button type="submit">Save a cup</button>
      </form>

      <ChaiList entries={entries} onDelete={onDelete} />
    </section>
  );
}


export default Home;
